def parse(s):
    out=[]
    for part in s.split(','):
        part=part.strip()
        if '-' in part: a,b=part.split('-'); out.append((int(a),int(b)))
        else: out.append((int(part),int(part)))
    return out
GROUPS=[(0,CAP),(1,MAJ),(2,RUR),(3,REM)]
def lookup(pc):
    n=int(pc)
    for z,grp in GROUPS:
        for name,s in grp.items():
            if any(a<=n<=b for a,b in parse(s)): return z,name
    return -1,''
